#!/usr/bin/env node
// Security audit script for environment configuration

const fs = require('fs');
const path = require('path');

console.log('🔒 Running Security Audit...\n');

// Check for .env files in git
const gitStatus = require('child_process').execSync('git status --porcelain').toString();
const envFilesInGit = gitStatus.includes('.env');

if (envFilesInGit) {
  console.log('❌ CRITICAL: .env files detected in git tracking');
  console.log('   Run: git rm --cached .env*');
} else {
  console.log('✅ No .env files tracked in git');
}

// Check .gitignore for env files
const gitignore = fs.readFileSync('.gitignore', 'utf8');
const envInGitignore = gitignore.includes('.env');

if (envInGitignore) {
  console.log('✅ .env files properly gitignored');
} else {
  console.log('❌ .env files not in .gitignore');
}

// Check for common insecure patterns
const checkFiles = ['.env', '.env.development', '.env.test'];

checkFiles.forEach(file => {
  if (fs.existsSync(file)) {
    const content = fs.readFileSync(file, 'utf8');

    // Check for common vulnerabilities
    if (content.includes('password') && content.length < 100) {
      console.log(`⚠️  ${file}: Short/weak passwords detected`);
    }

    if (content.includes('localhost') && content.includes('production')) {
      console.log(`⚠️  ${file}: Production configuration pointing to localhost`);
    }

    console.log(`✅ ${file}: Environment file exists`);
  } else {
    console.log(`ℹ️  ${file}: Not found (expected for production)`);
  }
});

console.log('\n🔒 Security audit completed');

