// Secrets management and validation
const Joi = require('joi');

// Schema for environment validation
const envSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().default(3000),

  // Security
  RATE_LIMIT_WINDOW_MS: Joi.number().default(900000),
  RATE_LIMIT_MAX_REQUESTS: Joi.number().default(100),

  // CORS
  ALLOWED_ORIGINS: Joi.string().default('http://localhost:3000,http://localhost:8080'),

  // Secrets (only required in production)
  DATABASE_URL: Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().required(),
    otherwise: Joi.string().optional()
  }),

  AWS_ACCESS_KEY_ID: Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().required(),
    otherwise: Joi.string().optional()
  }),

  AWS_SECRET_ACCESS_KEY: Joi.when('NODE_ENV', {
    is: 'production',
    then: Joi.string().required(),
    otherwise: Joi.string().optional()
  })
}).unknown(true);

const { error, value: envVars } = envSchema.validate(process.env);
if (error) {
  throw new Error(`Config validation error: ${error.message}`);
}

// Export validated configuration
module.exports = {
  env: envVars.NODE_ENV,
  port: envVars.PORT,

  // Security
  rateLimit: {
    windowMs: envVars.RATE_LIMIT_WINDOW_MS,
    max: envVars.RATE_LIMIT_MAX_REQUESTS
  },

  // CORS
  cors: {
    origins: envVars.ALLOWED_ORIGINS ? envVars.ALLOWED_ORIGINS.split(',') : []
  },

  // Secrets (masked in logs)
  database: {
    url: envVars.DATABASE_URL
  },

  aws: {
    accessKeyId: envVars.AWS_ACCESS_KEY_ID,
    secretAccessKey: envVars.AWS_SECRET_ACCESS_KEY
  }
};

