  async loadFromEncryptedEnv() {
    try {
      // In a real implementation, this would decrypt an encrypted file
      // For now, we'll validate that required environment variables exist
      this.validateRequiredSecrets();
    } catch (error) {
      console.warn('Using fallback environment variables');
    }
  }

  /**
   * Validate that all required secrets are available
   */
  validateRequiredSecrets() {
    const requiredSecrets = [
      'DATABASE_URL',
      'API_KEY',
      'JWT_SECRET',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const missingSecrets = requiredSecrets.filter(secret => 
      !process.env[secret] && !this.secrets.has(secret)
    );

    if (missingSecrets.length > 0) {
      throw new Error(`Missing required secrets: ${missingSecrets.join(', ')}`);
    }

    // Load from environment as fallback
    requiredSecrets.forEach(secret => {
      if (process.env[secret] && !this.secrets.has(secret)) {
        this.secrets.set(secret, process.env[secret]);
      }
    });
  }

  /**
   * Get a secret - main interface for application code
   */
  getSecret(key) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }

    const value = this.secrets.get(key);
    if (!value) {
      throw new Error(`Secret not found: ${key}`);
    }

    // Log secret access (without value) for auditing
    console.log(`Secret accessed: ${key} (from ${process.env.NODE_ENV || 'development'})`);

    return value;
  }

  /**
   * Check if a secret exists
   */
  hasSecret(key) {
    return this.secrets.has(key);
  }

