// Secure Environment Configuration Loader
// Prevents accidental exposure of .env files

const path = require('path');
const fs = require('fs').promises;

class SecureConfigLoader {
  constructor() {
    this.envFiles = [
      '.env.production',
      '.env.staging', 
      '.env.development',
      '.env.test',
      '.env'
    ];
    this.loaded = false;
  }

  /**
   * Load environment configuration securely
   */
  async load() {
    if (this.loaded) return;

    // Determine environment
    const nodeEnv = process.env.NODE_ENV || 'development';

    try {
      // Load environment-specific file first
      const envFile = `.env.${nodeEnv}`;

      if (await this.fileExists(envFile)) {
        await this.loadEnvFile(envFile);
        console.log(`Loaded environment from: ${envFile}`);
      } else {
        // Fallback to .env
        if (await this.fileExists('.env')) {
          await this.loadEnvFile('.env');
          console.log('Loaded environment from: .env');
        } else {
          console.warn('No .env file found, using process environment');
        }
      }

      this.validateEnvironment();
      this.loaded = true;

    } catch (error) {
      console.error('Failed to load environment configuration:', error.message);
      throw error;
    }
  }

  /**
   * Check if file exists
   */
  async fileExists(filePath) {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Load .env file safely
   */
  async loadEnvFile(filePath) {
    try {
      const content = await fs.readFile(filePath, 'utf8');
      const lines = content.split('\n');

      for (const line of lines) {
        const trimmed = line.trim();

        // Skip comments and empty lines
        if (!trimmed || trimmed.startsWith('#') || !trimmed.includes('=')) {
          continue;
        }

        const [key, ...valueParts] = trimmed.split('=');
        const value = valueParts.join('=').trim();

        // Only set if not already defined in process environment
        if (key && !process.env[key]) {
          process.env[key] = value;
        }
      }

    } catch (error) {
      console.warn(`Could not read ${filePath}:`, error.message);
    }
  }

  /**
   * Validate required environment variables
   */
  validateEnvironment() {
    const requiredVars = {
      development: ['DATABASE_URL', 'API_KEY', 'JWT_SECRET'],
      test: ['DATABASE_URL', 'API_KEY'],
      production: [
        'DATABASE_URL', 
        'API_KEY', 
        'JWT_SECRET', 
        'AWS_ACCESS_KEY_ID',
        'AWS_SECRET_ACCESS_KEY'
      ]
    };

    const nodeEnv = process.env.NODE_ENV || 'development';
    const required = requiredVars[nodeEnv] || requiredVars.development;

    const missing = required.filter(varName => !process.env[varName]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables for ${nodeEnv}: ${missing.join(', ')}`);
    }

    // Validate secret lengths
    this.validateSecretLengths();
  }

  /**
   * Validate that secrets meet minimum security requirements
   */
  validateSecretLengths() {
    const secretValidations = {
      JWT_SECRET: { min: 32, description: 'JWT Secret' },
      API_KEY: { min: 16, description: 'API Key' },
      SESSION_SECRET: { min: 32, description: 'Session Secret' }
    };

    for (const [key, validation] of Object.entries(secretValidations)) {
      if (process.env[key] && process.env[key].length < validation.min) {
        console.warn(`SECURITY WARNING: ${validation.description} is too short (${process.env[key].length} < ${validation.min} chars)`);
      }
    }
  }

  /**
   * Get all environment variables (for debugging, without sensitive values)
   */
  getEnvironmentSummary() {
    const summary = {};
    const sensitiveKeys = ['KEY', 'SECRET', 'PASSWORD', 'TOKEN', 'CREDENTIAL'];

    Object.entries(process.env).forEach(([key, value]) => {
      const isSensitive = sensitiveKeys.some(sensitive => 
        key.toUpperCase().includes(sensitive)
      );

      summary[key] = isSensitive ? '••••••••' : value;
    });

    return summary;
  }
}

