// Use this to validate and assist with credential rotation

const crypto = require('crypto');

class RotationHelper {
  constructor() {
    this.canaryPatterns = [
      'CANARY',
      'canary', 
      'test-credentials',
      'example',
      'demo',
      'placeholder'
    ];
  }

  /**
   * Analyze environment for canary credentials
   */
  analyzeEnvironment() {
    const results = [];
    const sensitiveVars = [
      'DATABASE_URL', 'AWS_', 'API_', 'SECRET', 'KEY', 'TOKEN', 'PASSWORD', 'CREDENTIAL'
    ];

    console.log('🔍 Scanning environment for canary credentials...\n');

    Object.entries(process.env).forEach(([key, value]) => {
      if (sensitiveVars.some(sensitive => key.toUpperCase().includes(sensitive))) {
        const isCanary = this.isCanaryCredential(value);
        if (isCanary) {
          results.push({
            variable: key,
            value: this.redactValue(value),
            isCanary: true,
            risk: this.assessRisk(key, value)
          });
        }
      }
    });

    return results;
  }

  /**
   * Check if value contains canary patterns
   */
  isCanaryCredential(value) {
    if (!value || typeof value !== 'string') return false;

    return this.canaryPatterns.some(pattern => 
      value.toUpperCase().includes(pattern.toUpperCase())
    );
  }

  /**
   * Redact sensitive values for display
   */
  redactValue(value, showFirst = 4, showLast = 4) {
    if (!value || value.length <= (showFirst + showLast)) {
      return '***';
    }

    const first = value.substring(0, showFirst);
    const last = value.substring(value.length - showLast);
    const middle = '*'.repeat(Math.max(0, value.length - showFirst - showLast));

    return `${first}${middle}${last}`;
  }

  /**
   * Assess risk level based on variable and value
   */
  assessRisk(variable, value) {
    const variableLower = variable.toLowerCase();

    // Critical risks
    if (variableLower.includes('stripe') && value.includes('_live_')) {
      return 'CRITICAL - LIVE payment credentials';
    }

    if (variableLower.includes('aws_access_key_id') && value.startsWith('AKIA')) {
      return 'CRITICAL - AWS production credentials';
    }

    if (variableLower.includes('database_url') && value.includes('production')) {
      return 'CRITICAL - Production database access';
    }

    // High risks
    if (variableLower.includes('secret') || variableLower.includes('key')) {
      return 'HIGH - API/Service credentials';
    }

    if (variableLower.includes('token')) {
      return 'HIGH - Access token compromised';
    }

    return 'MEDIUM - General credentials';
  }

  /**
   * Generate secure replacement credentials
   */
  generateSecureCredential(type, length = 32) {
    const generators = {
      'api-key': () => `sk_${this.generateRandomString(length)}`,
      'secret': () => this.generateRandomString(length),
      'password': () => this.generateRandomString(length),
      'token': () => this.generateRandomString(length),
      'default': () => this.generateRandomString(length)
    };

    const generator = generators[type] || generators.default;
    return generator();
  }

  /**
   * Generate cryptographically secure random string
   */
  generateRandomString(length) {
    return crypto.randomBytes(Math.ceil(length / 2))
      .toString('hex')
      .slice(0, length);
  }

  /**
   * Validate credential strength
   */
  validateCredentialStrength(credential, type = 'secret') {
    const validations = {
      'api-key': { minLength: 20, requiresPrefix: true },
      'secret': { minLength: 32, requiresSpecial: true },
      'password': { minLength: 16, requiresSpecial: true, requiresNumbers: true },
      'token': { minLength: 24 }
    };

    const validation = validations[type] || validations.secret;
    const issues = [];

    if (credential.length < validation.minLength) {
      issues.push(`Too short (min ${validation.minLength} chars)`);
    }

    if (validation.requiresSpecial && !/[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(credential)) {
