      username: user.username, 
      role: user.role 
    },
    process.env.JWT_SECRET,
    { expiresIn: '1h' }
  );

  res.json({ 
    token, 
    user: { 
      id: user.id, 
      username: user.username, 
      role: user.role 
    }
  });
};

module.exports = {
  authenticateToken,
  authorize,
  login
};

