// Secret Manager abstraction layer
// Supports multiple backends: environment, AWS Secrets Manager, HashiCorp Vault

class SecretManager {
  constructor() {
    this.backend = this.determineBackend();
  }

  determineBackend() {
    // Determine which secret backend to use based on environment
    if (process.env.AWS_SECRETS_MANAGER_ENABLED === 'true') {
      return 'aws';
    } else if (process.env.VAULT_ENABLED === 'true') {
      return 'vault';
    } else if (process.env.GCP_SECRET_MANAGER_ENABLED === 'true') {
      return 'gcp';
    }
    return 'env'; // Fallback to environment variables
  }

  async getSecret(secretName, defaultValue = null) {
    try {
      switch (this.backend) {
        case 'aws':
          return await this.getFromAWSSecretsManager(secretName);
        case 'vault':
          return await this.getFromVault(secretName);
        case 'gcp':
          return await this.getFromGCPSecretManager(secretName);
        default:
          return this.getFromEnv(secretName, defaultValue);
      }
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);

      // In production, we might want to fail hard, but for development
      // we can fallback to environment variables with a warning
      if (process.env.NODE_ENV === 'production') {
        throw new Error(`Secret ${secretName} is required but unavailable`);
      }

      console.warn(`Falling back to environment variable for ${secretName}`);
      return this.getFromEnv(secretName, defaultValue);
    }
  }

  getFromEnv(secretName, defaultValue) {
    const value = process.env[secretName];
    if (value === undefined && defaultValue === null) {
      throw new Error(`Environment variable ${secretName} is not set`);
    }
    return value || defaultValue;
  }

  async getFromAWSSecretsManager(secretName) {
    // AWS Secrets Manager implementation
    // This would require AWS SDK and proper IAM permissions
    const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const response = await client.getSecretValue({ SecretId: secretName });
      if ('SecretString' in response) {
        return response.SecretString;
      } else {
        const buff = Buffer.from(response.SecretBinary, 'base64');
        return buff.toString('ascii');
      }
    } catch (error) {
      console.error('AWS Secrets Manager error:', error);
      throw error;
    }
  }

  async getFromVault(secretName) {
    // HashiCorp Vault implementation
    // This would require node-vault or similar library
    const vault = require('node-vault')({
      apiVersion: 'v1',
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    try {
      const secret = await vault.read(secretName);
      return secret.data.value;
    } catch (error) {
      console.error('Vault error:', error);
      throw error;
    }
  }

  async getFromGCPSecretManager(secretName) {
    // Google Cloud Secret Manager implementation
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

    const client = new SecretManagerServiceClient();

    try {
      const [version] = await client.accessSecretVersion({
        name: `projects/${process.env.GCP_PROJECT_ID}/secrets/${secretName}/versions/latest`,
      });

      return version.payload.data.toString('utf8');
    } catch (error) {
      console.error('GCP Secret Manager error:', error);
      throw error;
    }
  }

  // Optional: Secret rotation and caching
  async getSecretWithCache(secretName, ttlMs = 300000) { // 5 minutes default
    // Implement caching with proper invalidation
    // This is useful for reducing API calls to secret managers
  }
}

// Singleton instance
const secretManager = new SecretManager();

module.exports = secretManager;

