// Configuration manager with secret integration
const secretManager = require('./secrets');

class Config {
  constructor() {
    this.configCache = new Map();
    this.requiredSecrets = [
      'JWT_SECRET',
      'SESSION_SECRET',
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY'
    ];
  }

  async initialize() {
    console.log('🔐 Initializing configuration with secret manager...');

    // Pre-load required secrets
    await this.preloadSecrets();

    console.log('✅ Configuration initialized');
  }

  async preloadSecrets() {
    for (const secretName of this.requiredSecrets) {
      try {
        const value = await secretManager.getSecret(secretName);
        if (value) {
          this.configCache.set(secretName, value);
        }
      } catch (error) {
        if (process.env.NODE_ENV === 'production') {
          console.error(`CRITICAL: Required secret ${secretName} not found`);
          process.exit(1);
        }
        console.warn(`Secret ${secretName} not available (development mode)`);
      }
    }
  }

  async get(key, defaultValue = null) {
    // Check cache first
    if (this.configCache.has(key)) {
      return this.configCache.get(key);
    }

    // Check if it's a secret that should be managed
    if (this.requiredSecrets.includes(key)) {
      const value = await secretManager.getSecret(key, defaultValue);
      this.configCache.set(key, value);
      return value;
    }

    // Fallback to environment variable
    return process.env[key] || defaultValue;
  }

  getSync(key, defaultValue = null) {
    // Synchronous version for values that should be pre-loaded
    if (this.configCache.has(key)) {
      return this.configCache.get(key);
    }

    return process.env[key] || defaultValue;
  }

  // Helper methods for specific configuration types
  async getJwtSecret() {
    return this.get('JWT_SECRET');
  }

  async getDatabaseUrl() {
    return this.get('DATABASE_URL');
  }

  async getAwsCredentials() {
    return {
      accessKeyId: await this.get('AWS_ACCESS_KEY_ID'),
      secretAccessKey: await this.get('AWS_SECRET_ACCESS_KEY'),
      region: await this.get('AWS_REGION', 'us-east-1')
    };
  }

  // Utility methods
  isProduction() {
    return this.getSync('NODE_ENV') === 'production';
  }

  isDevelopment() {
    return this.getSync('NODE_ENV') === 'development' || !this.getSync('NODE_ENV');
  }

  getPort() {
    return parseInt(this.getSync('PORT', '3000'));
  }

  getHost() {
    return this.getSync('HOST', 'localhost');
  }
}

// Singleton instance
const config = new Config();

// Async initialization wrapper
const initializeConfig = async () => {
  await config.initialize();
  return config;
};

module.exports = { config, initializeConfig };

