const express = require('express');
const app = express();
const {
  securityHeaders,
  limiter,
  validateInput,
  errorHandler
} = require('./security-middleware');

// Load environment variables securely
require('dotenv').config({ path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env' });

// Security middleware setup
app.use(securityHeaders);
app.use(limiter);
app.use(validateInput);
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  // Validate and sanitize any query parameters
  const { debug } = req.query;

  const response = { 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  };

  // Only include debug info if explicitly requested and authorized
  if (debug === 'true' && process.env.NODE_ENV === 'development') {
    response.uptime = process.uptime();
    response.memory = process.memoryUsage();
  }

  res.json(response);
});

// Users endpoint with proper data validation
app.get('/users', (req, res) => {
  // Validate query parameters
