// Security audit script for the Express application
const { execSync } = require('child_process');
const fs = require('fs');

console.log('🔒 Starting Security Audit...\n');

// Check for common security issues
try {
  // 1. Check for vulnerable dependencies
  console.log('1. Checking for vulnerable dependencies...');
  try {
    const auditResult = execSync('npm audit --json', { encoding: 'utf8' });
    const auditData = JSON.parse(auditResult);

    if (auditData.metadata.vulnerabilities.total > 0) {
      console.log('❌ Vulnerabilities found:');
      console.log(`   - Critical: ${auditData.metadata.vulnerabilities.critical}`);
      console.log(`   - High: ${auditData.metadata.vulnerabilities.high}`);
      console.log(`   - Moderate: ${auditData.metadata.vulnerabilities.moderate}`);
      console.log(`   - Low: ${auditData.metadata.vulnerabilities.low}`);
    } else {
      console.log('✅ No known vulnerabilities found');
    }
  } catch (error) {
    console.log('⚠️  npm audit failed - check npm version');
  }

  // 2. Check for environment files
  console.log('\n2. Checking environment configuration...');
  const envFiles = ['.env', '.env.local', '.env.test'];
  let hasExposedEnv = false;

  envFiles.forEach(file => {
    if (fs.existsSync(file)) {
      const content = fs.readFileSync(file, 'utf8');
      if (content.includes('secret') || content.includes('key') || content.includes('password')) {
        console.log(`❌ ${file} contains potential secrets`);
        hasExposedEnv = true;
      } else {
        console.log(`✅ ${file} looks clean`);
      }
    }
  });

  if (!hasExposedEnv) {
    console.log('✅ No exposed secrets found in environment files');
  }

  // 3. Check gitignore
  console.log('\n3. Checking .gitignore...');
  if (fs.existsSync('.gitignore')) {
    const gitignore = fs.readFileSync('.gitignore', 'utf8');
    const requiredPatterns = ['.env', 'node_modules', 'logs'];
    const missingPatterns = requiredPatterns.filter(pattern => !gitignore.includes(pattern));

    if (missingPatterns.length === 0) {
      console.log('✅ .gitignore properly configured');
    } else {
      console.log(`❌ Missing patterns in .gitignore: ${missingPatterns.join(', ')}`);
    }
  } else {
    console.log('❌ No .gitignore file found');
  }

  // 4. Check for security middleware
  console.log('\n4. Checking security middleware...');
  if (fs.existsSync('security-middleware.js')) {
    const middleware = fs.readFileSync('security-middleware.js', 'utf8');
    const securityFeatures = [
      'helmet',
      'rateLimit',
      'validateInput',
      'errorHandler'
    ];

    const implementedFeatures = securityFeatures.filter(feature => middleware.includes(feature));
    console.log(`✅ Security features implemented: ${implementedFeatures.length}/${securityFeatures.length}`);

    if (implementedFeatures.length < securityFeatures.length) {
      const missing = securityFeatures.filter(f => !implementedFeatures.includes(f));
      console.log(`   Missing: ${missing.join(', ')}`);
    }
  } else {
    console.log('❌ No security middleware found');
  }

  console.log('\n🔒 Security audit completed!');
  console.log('\nRecommendations:');
  console.log('- Run \'npm run security-scan\' regularly');
  console.log('- Set up CI/CD security scanning');
  console.log('- Use secret management (AWS Secrets Manager, HashiCorp Vault)');
  console.log('- Implement proper authentication (JWT, OAuth2)');
  console.log('- Add database encryption for sensitive data');

} catch (error) {
  console.error('Audit failed:', error.message);
}

