// Secure secret management with validation and encryption
const crypto = require('crypto');

class SecretManager {
  constructor() {
    this.secrets = new Map();
    this.encryptionKey = process.env.ENCRYPTION_KEY || this.generateTempKey();
  }

  // Generate temporary encryption key (for development only)
  generateTempKey() {
    console.warn('⚠️  Using temporary encryption key - not for production!');
    return crypto.randomBytes(32).toString('hex');
  }

  // Validate required environment variables
  validateEnvVars(requiredVars = []) {
    const missing = [];
    const presentButEmpty = [];

    requiredVars.forEach(varName => {
      if (!(varName in process.env)) {
        missing.push(varName);
      } else if (!process.env[varName] || process.env[varName].trim() === '') {
        presentButEmpty.push(varName);
      }
    });

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }

    if (presentButEmpty.length > 0) {
      console.warn(`⚠️  Empty environment variables: ${presentButEmpty.join(', ')}`);
    }

    return true;
  }

  // Encrypt sensitive values
  encrypt(value) {
    if (!value) return value;

    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(this.encryptionKey, 'hex'), iv);

    let encrypted = cipher.update(value, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag().toString('hex');

    return `${iv.toString('hex')}:${encrypted}:${authTag}`;
  }

  // Decrypt sensitive values
  decrypt(encryptedValue) {
    if (!encryptedValue || !encryptedValue.includes(':')) return encryptedValue;

    const [ivHex, encrypted, authTag] = encryptedValue.split(':');
    const iv = Buffer.from(ivHex, 'hex');
    const decipher = crypto.createDecipheriv('aes-256-gcm', Buffer.from(this.encryptionKey, 'hex'), iv);

    decipher.setAuthTag(Buffer.from(authTag, 'hex'));

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  // Store secret with optional encryption
  set(key, value, encrypt = true) {
    const processedValue = encrypt ? this.encrypt(value) : value;
    this.secrets.set(key, processedValue);
    return this;
  }

  // Retrieve secret with automatic decryption
  get(key, defaultValue = null) {
    const value = this.secrets.get(key) || process.env[key] || defaultValue;

    // Auto-detect and decrypt encrypted values
    if (value && typeof value === 'string' && value.includes(':') && value.split(':').length === 3) {
      try {
        return this.decrypt(value);
      } catch (error) {
        console.warn(`Failed to decrypt value for key ${key}:`, error.message);
        return defaultValue;
      }
    }

    return value;
  }

  // Load secrets from environment with validation
  loadFromEnv(config = {}) {
    const { required = [], optional = [], encryptSensitive = true } = config;

    // Validate required variables
    this.validateEnvVars(required);

    // Load all variables
    const allVars = [...required, ...optional];

    allVars.forEach(key => {
      if (process.env[key]) {
        const shouldEncrypt = encryptSensitive && 
          (key.toLowerCase().includes('secret') || 
           key.toLowerCase().includes('key') || 
           key.toLowerCase().includes('password') ||
           key.toLowerCase().includes('token'));

        this.set(key, process.env[key], shouldEncrypt);
      }
    });

    return this;
  }
}

// Default configuration for common secrets
const DEFAULT_SECRET_CONFIG = {
  required: [
    'NODE_ENV',
    'PORT'
  ],
  optional: [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
    'SESSION_SECRET',
    'JWT_SECRET',
    'ENCRYPTION_KEY'
  ],
  encryptSensitive: true
};

// Create and configure secret manager instance
const secretManager = new SecretManager();

// Initialize with default configuration
try {
  secretManager.loadFromEnv(DEFAULT_SECRET_CONFIG);
  console.log('✅ Secret manager initialized successfully');
} catch (error) {
  console.error('❌ Failed to initialize secret manager:', error.message);
  process.exit(1);
}

module.exports = secretManager;

