// Secrets management with validation and fallbacks
class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loadSecrets();
  }

  loadSecrets() {
    // Load from environment variables (primary source)
    this.secrets = {
      jwtSecret: process.env.JWT_SECRET,
      databaseUrl: process.env.DATABASE_URL,
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      anthropicApiKey: process.env.ANTHROPIC_API_KEY,
      logfireToken: process.env.LOGFIRE_TOKEN
    };

    this.validateSecrets();
  }

  validateSecrets() {
    const requiredInProduction = ['jwtSecret'];

    if (process.env.NODE_ENV === 'production') {
      requiredInProduction.push('databaseUrl');
    }

    const missing = requiredInProduction.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Warn about missing optional secrets
    const optionalSecrets = ['awsAccessKeyId', 'awsSecretAccessKey', 'stripeSecretKey', 'anthropicApiKey', 'logfireToken'];
    const missingOptional = optionalSecrets.filter(key => !this.secrets[key]);

    if (missingOptional.length > 0 && process.env.NODE_ENV !== 'test') {
      console.warn('⚠️  Missing optional secrets:', missingOptional.join(', '));
    }
  }

  get(key) {
    const value = this.secrets[key];
    if (!value && process.env.NODE_ENV === 'production') {
      throw new Error(`Secret ${key} not found`);
    }
    return value;
  }

  getAll() {
    return { ...this.secrets };
  }
}

// Singleton instance
module.exports = new SecretsManager();

